<template>
 <section class="midi-import" role="group" :aria-label="$t(sourceMode==='native'?'Crear una versión editable':'Preparar MIDI para SPC700')">
  <header><strong>{{ $t(sourceMode==='native'?'Crear una versión editable':'Preparar MIDI para SPC700') }}</strong><button @click="$emit('cancel')">{{ $t('Cancelar') }}</button></header>
  <p>{{ filename }} · {{parsed.notes}} {{ $t('notas') }} · {{Math.ceil(parsed.duration/192)}} {{ $t('compases') }}</p>
  <p>{{ $t(sourceMode==='native'?'Para dibujar notas, crea una versión simple del fragmento. Se conservan sus notas y tiempos; se sustituyen los instrumentos y se eliminan los efectos y comandos nativos. Puedes deshacer la conversión.':'Elige el fragmento y las voces antes de importar. El archivo original se conserva completo.') }}</p>
  <div class="fragment"><label>{{ $t('Compás inicial') }} <input type="number" v-model.number="startBar" min="1" :max="Math.max(1,Math.ceil(parsed.duration/192))" /></label><label>{{ $t('Compases a importar') }} <input type="number" v-model.number="bars" min="1" max="256" /></label><span>{{ $t('Voces utilizadas') }} {{voices.reduce((a,b)=>a+b,0)}} / {{channels}}</span></div>
  <div class="midi-channels"><div v-for="(channel,i) in parsed.channels" :key="channel.id"><span>{{channel.name||$t('Canal')}} · {{channel.id+1}}<small>{{channel.notes.length}} {{ $t('notas') }} · {{ $t('Polifonía máxima') }} {{channel.polyphony}}</small></span><label>{{ $t('Voces') }} <input type="number" v-model.number="voices[i]" min="0" :max="channels" /></label><label>{{ $t('Instrumento SNES') }} <select v-model.number="instruments[i]"><option v-for="n in 30" :key="n" :value="n-1">{{n-1}}</option></select></label></div></div>
  <p>{{ $t(sourceMode==='native'?'Elige el fragmento y los instrumentos de la versión editable. Los bucles se expanden como notas; sus comandos originales no se mantienen.':'Los acordes se reparten entre voces monofónicas. Las notas que exceden las voces elegidas se omiten. Los instrumentos MIDI se sustituyen por los instrumentos SNES seleccionados.') }}</p>
  <div v-if="result" class="report" role="status"><span>{{ $t('Notas del fragmento') }}: {{result.selected}}</span><span>{{ $t('Notas omitidas') }}: {{result.omitted}}</span><span>{{ $t('Notas largas divididas') }}: {{result.split}}</span><span>{{ $t('Notas transpuestas por rango') }}: {{result.shifted}}</span><span>{{ $t('Espacio comprimido') }}: {{result.size}} / {{capacity}} B</span><span v-if="sourceMode!=='native'">{{ $t('Controles o efectos MIDI no importados') }}: {{result.ignored}}</span><span v-if="result.tempoChanges">{{ $t('Los cambios de tempo se convierten a posiciones con tempo constante.') }}</span><span v-if="result.unmatched">{{ $t('Notas con cierre reparado') }}: {{result.unmatched}}</span></div>
  <p v-if="error" class="import-error" role="alert">{{ $t(error) }}</p>
  <button :disabled="!result" @click="$emit('confirm',{...result,startBar,bars,filename})">{{ $t(sourceMode==='native'?'Crear versión editable y dibujar':'Importar fragmento al borrador') }}</button>
 </section>
</template>
<script>
import {convertMidi,defaultMidiVoices} from '../rom/music-midi-import.mjs';
export default {props:{parsed:Object,filename:String,channels:Number,capacity:Number,sourceMode:{type:String,default:'midi'}},emits:['cancel','confirm'],data(){return {startBar:1,bars:Math.min(8,Math.max(1,Math.ceil(this.parsed.duration/192))),voices:defaultMidiVoices(this.parsed,this.channels),instruments:this.parsed.channels.map(()=>1)};},computed:{conversion(){try{return {result:convertMidi(this.parsed,{channels:this.channels,capacity:this.capacity,startBar:this.startBar,bars:this.bars,voices:this.voices,instruments:this.instruments}),error:''};}catch(error){return {result:null,error:error.message};}},result(){return this.conversion.result;},error(){return this.conversion.error;}}};
</script>
<style scoped>
.midi-import{padding:16px;margin:12px 0;background:#1d2d40;border:1px solid #7899bb;border-radius:8px;color:#d9e8f7}.midi-import header,.fragment,.midi-channels>div{display:flex;align-items:center;gap:15px;flex-wrap:wrap}.midi-import header{justify-content:space-between}.midi-import p{line-height:1.6;font-size:12px}.midi-import label{display:flex;align-items:center;gap:7px;font-size:12px}.midi-import button,.midi-import input,.midi-import select{font:inherit;background:#253b50;color:#e0efff;border:1px solid #718aa4;border-radius:4px;padding:6px}.midi-import button{cursor:pointer}.midi-import button:disabled{opacity:.4;cursor:default}.midi-import input{width:65px}.midi-channels{margin:14px 0}.midi-channels>div{padding:9px 0;border-bottom:1px solid #476078}.midi-channels>div>span{min-width:180px;flex:1}.midi-channels small{display:block;font-size:10px;color:#b3c5d9;margin-top:4px}.report{display:flex;gap:8px 18px;flex-wrap:wrap;padding:10px;background:#101e2e;font-size:12px;margin-bottom:12px}.import-error{color:#ffd2b2}.midi-import :focus-visible{outline:2px solid #9ad9ff;outline-offset:2px}
</style>
